BEGIN;
ALTER TABLE public.hero_items ADD COLUMN IF NOT EXISTS title_bn text, ADD COLUMN IF NOT EXISTS title_en text, ADD COLUMN IF NOT EXISTS description_bn text, ADD COLUMN IF NOT EXISTS description_en text;
ALTER TABLE public.post ADD COLUMN IF NOT EXISTS title_bn text, ADD COLUMN IF NOT EXISTS title_en text, ADD COLUMN IF NOT EXISTS caption_bn text, ADD COLUMN IF NOT EXISTS caption_en text, ADD COLUMN IF NOT EXISTS description_bn text, ADD COLUMN IF NOT EXISTS description_en text, ADD COLUMN IF NOT EXISTS content_bn text, ADD COLUMN IF NOT EXISTS content_en text;
ALTER TABLE public.pages ADD COLUMN IF NOT EXISTS title_bn text, ADD COLUMN IF NOT EXISTS title_en text, ADD COLUMN IF NOT EXISTS description_bn text, ADD COLUMN IF NOT EXISTS description_en text, ADD COLUMN IF NOT EXISTS content_bn text, ADD COLUMN IF NOT EXISTS content_en text;
ALTER TABLE public.albums ADD COLUMN IF NOT EXISTS title_bn text, ADD COLUMN IF NOT EXISTS title_en text, ADD COLUMN IF NOT EXISTS description_bn text, ADD COLUMN IF NOT EXISTS description_en text;
ALTER TABLE public.widgets ADD COLUMN IF NOT EXISTS title_bn text, ADD COLUMN IF NOT EXISTS title_en text;
UPDATE public.hero_items SET title_bn=CASE WHEN title ~ '[ঀ-৿]' THEN title ELSE title_bn END,title_en=CASE WHEN title !~ '[ঀ-৿]' THEN title ELSE title_en END,description_bn=CASE WHEN COALESCE(description,'') ~ '[ঀ-৿]' THEN description ELSE description_bn END,description_en=CASE WHEN COALESCE(description,'')<>'' AND description !~ '[ঀ-৿]' THEN description ELSE description_en END WHERE title_bn IS NULL OR title_en IS NULL OR description_bn IS NULL OR description_en IS NULL;
UPDATE public.post SET title_bn=CASE WHEN title ~ '[ঀ-৿]' THEN title ELSE title_bn END,title_en=CASE WHEN title !~ '[ঀ-৿]' THEN title ELSE title_en END,caption_bn=CASE WHEN COALESCE(caption,'') ~ '[ঀ-৿]' THEN caption ELSE caption_bn END,caption_en=CASE WHEN COALESCE(caption,'')<>'' AND caption !~ '[ঀ-৿]' THEN caption ELSE caption_en END,description_bn=CASE WHEN COALESCE(description,'') ~ '[ঀ-৿]' THEN description ELSE description_bn END,description_en=CASE WHEN COALESCE(description,'')<>'' AND description !~ '[ঀ-৿]' THEN description ELSE description_en END,content_bn=CASE WHEN COALESCE(content,'') ~ '[ঀ-৿]' THEN content ELSE content_bn END,content_en=CASE WHEN COALESCE(content,'')<>'' AND content !~ '[ঀ-৿]' THEN content ELSE content_en END WHERE title_bn IS NULL OR title_en IS NULL OR caption_bn IS NULL OR caption_en IS NULL OR description_bn IS NULL OR description_en IS NULL OR content_bn IS NULL OR content_en IS NULL;
UPDATE public.pages SET title_bn=CASE WHEN title ~ '[ঀ-৿]' THEN title ELSE title_bn END,title_en=CASE WHEN title !~ '[ঀ-৿]' THEN title ELSE title_en END,description_bn=CASE WHEN COALESCE(description,'') ~ '[ঀ-৿]' THEN description ELSE description_bn END,description_en=CASE WHEN COALESCE(description,'')<>'' AND description !~ '[ঀ-৿]' THEN description ELSE description_en END,content_bn=CASE WHEN COALESCE(content,'') ~ '[ঀ-৿]' THEN content ELSE content_bn END,content_en=CASE WHEN COALESCE(content,'')<>'' AND content !~ '[ঀ-৿]' THEN content ELSE content_en END WHERE title_bn IS NULL OR title_en IS NULL OR description_bn IS NULL OR description_en IS NULL OR content_bn IS NULL OR content_en IS NULL;
UPDATE public.albums SET title_bn=CASE WHEN title ~ '[ঀ-৿]' THEN title ELSE title_bn END,title_en=CASE WHEN title !~ '[ঀ-৿]' THEN title ELSE title_en END,description_bn=CASE WHEN COALESCE(description,'') ~ '[ঀ-৿]' THEN description ELSE description_bn END,description_en=CASE WHEN COALESCE(description,'')<>'' AND description !~ '[ঀ-৿]' THEN description ELSE description_en END WHERE title_bn IS NULL OR title_en IS NULL OR description_bn IS NULL OR description_en IS NULL;
UPDATE public.widgets SET title_bn=CASE WHEN title ~ '[ঀ-৿]' THEN title ELSE title_bn END,title_en=CASE WHEN title !~ '[ঀ-৿]' THEN title ELSE title_en END WHERE title_bn IS NULL OR title_en IS NULL;
NOTIFY pgrst, 'reload schema';
COMMIT;
